def _claim_turn_or_queue(self, state: SessionState, session_id: str, user_text: str, user_content: Any, text_only: bool) -> str | None:
    """Mark the session running; if a turn is active, redirect it (text-only, supported
        runtime) or queue it. Returns the client message when absorbed, else None."""
    with state.runtime_lock:
        if not state.is_running:
            state.is_running = True
            state.current_prompt_text = user_text or '[Image attachment]'
            return None
        if text_only and isinstance(user_content, str) and hasattr(state.agent, 'redirect') and (getattr(state.agent, '_supports_active_turn_redirect', False) is True):
            try:
                if state.agent.redirect(user_content):
                    return 'Redirected the active turn with your correction.'
            except Exception:
                logger.debug('ACP active-turn redirect failed for %s', session_id, exc_info=True)
        state.queued_prompts.append(user_text or '[Image attachment]')
        return f'Queued for the next turn. ({len(state.queued_prompts)} queued)'

def prepare_iteration(agent: Any, *, messages: Any, api_call_count: Any, user_message: Any=None, current_turn_user_idx: Any=None) -> IterationPrep:
    """Prepare ``messages`` for this iteration in the original order. Every mutation here is
    cache-safe by construction: steer text is appended as a new (not yet persisted) user row, the ghost-row
    filter only drops hidden scaffold placeholders, and repair runs BEFORE the request build."""
    from agent.conversation_loop import _INTERRUPT_SCAFFOLD_MARKER, _maybe_inject_run_budget_wrapup
    if getattr(agent, '_nous_wire_pending', None):
        from agent.nous_wire import apply_pending_wire_switch
        apply_pending_wire_switch(agent)
    if agent.step_callback is not None:
        try:
            agent.step_callback(api_call_count, _previous_tool_round(messages))
        except Exception as _step_err:
            logger.debug('step_callback error (iteration %s): %s', api_call_count, _step_err)
    if agent._skill_nudge_interval > 0 and 'skill_manage' in agent.valid_tool_names:
        agent._iters_since_skill += 1
    try:
        agent._adopt_nous_key_before_expiry()
    except Exception:
        logger.debug('Nous key pre-expiry adoption failed', exc_info=True)
    _pre_api_steer = agent._drain_pending_steer()
    if _pre_api_steer:
        _inject_steer_after_newest_tool_result(agent, messages, _pre_api_steer)
    if getattr(agent, 'run_budget_seconds', None):
        _maybe_inject_run_budget_wrapup(agent, messages)
    _maybe_inject_iteration_budget_warning(agent, messages)
    request_logger = getattr(agent, 'logger', None) or logger
    _sanitize_cursor = getattr(agent, '_sanitize_args_cursor', None)
    if _sanitize_cursor is None:
        _sanitize_cursor = {}
        with suppress(Exception):
            agent._sanitize_args_cursor = _sanitize_cursor
    repaired_tool_calls = agent._sanitize_tool_call_arguments(messages, logger=request_logger, session_id=agent.session_id, cursor=_sanitize_cursor)
    if repaired_tool_calls > 0:
        request_logger.info('Sanitized %s corrupted tool_call arguments before request (session=%s)', repaired_tool_calls, agent.session_id or '-')

    def _is_scaffold_ghost(msg: Dict[str, Any]) -> bool:
        return msg.get('display_kind') == 'hidden' and msg.get('role') == 'assistant' and any((isinstance(msg.get(k), str) and msg[k].strip() == _INTERRUPT_SCAFFOLD_MARKER for k in ('content', 'api_content')))
    messages = [msg for msg in messages if not _is_scaffold_ghost(msg)]
    from agent.agent_runtime_helpers import repair_message_sequence_with_cursor
    repaired_seq = repair_message_sequence_with_cursor(agent, messages)
    if repaired_seq > 0:
        request_logger.info('Repaired %s message-alternation violations before request (session=%s)', repaired_seq, agent.session_id or '-')
        if user_message is not None:
            _reanchored_idx = _reanchor(agent, messages, user_message)
            if _reanchored_idx != current_turn_user_idx:
                request_logger.info('Re-anchored current_turn_user_idx %s -> %s after alternation repair (session=%s)', current_turn_user_idx, _reanchored_idx, agent.session_id or '-')
                current_turn_user_idx = _reanchored_idx
    return IterationPrep(action='fallthrough', messages=messages, request_logger=request_logger, current_turn_user_idx=current_turn_user_idx)

def format_steer_marker(steer_text: str) -> str:
    """Wrap a mid-turn steer in the self-describing marker (see note above)."""
    return f'

{STEER_MARKER_OPEN}
{steer_text}
{STEER_MARKER_CLOSE}'

def steer_user_row(steer_text: str) -> Dict[str, Any]:
    """The standalone ``role:user`` row a mid-turn /steer is delivered as (after the newest tool
    result). Its own row — never smeared onto the already-persisted tool row, which append-only
    persistence would leave divergent from the live request — and typed so the alternation repair
    never merges the next real prompt into it and history renderers can label it."""
    return {'role': 'user', 'content': format_steer_marker(steer_text).lstrip(), 'display_kind': STEER_DISPLAY_KIND}

def _make_func(self, model: type[BaseModel], obj: Any, attr: str) -> AsyncHandler | None:
    (func, attr, legacy_api) = _resolve_handler(obj, attr)
    if func is None:
        return None

    async def wrapper(params: Any) -> Any:
        if legacy_api:
            _warn_legacy_handler(obj, attr)
        model_obj = model.model_validate(params)
        if legacy_api:
            return await func(model_obj)
        params = {k: getattr(model_obj, k) for k in model.model_fields if k != 'field_meta'}
        if (meta := getattr(model_obj, 'field_meta', None)):
            params.update(meta)
        return await func(**params)
    return wrapper

def _ic_slot(agent, lock_attr: str, slot: str):
    """Read the pending-text ``slot`` guarded by ``lock_attr``. An initialized agent always has both
    attributes, so under the lock the slot is read directly and a missing one fails loud (a real bug);
    only ``__init__``-less test stubs (no lock) get the ``getattr`` fallback."""
    if getattr(agent, lock_attr, None) is None:
        return getattr(agent, slot, None)
    return getattr(agent, slot)

def _requeue_pending_steer(agent, steer_text: str) -> None:
    """Put drained steer text back so the caller's fallback delivers it as a next-turn user message."""
    _lock = getattr(agent, '_pending_steer_lock', None)
    if _lock is not None:
        with _lock:
            if agent._pending_steer:
                agent._pending_steer = agent._pending_steer + '\n' + steer_text
            else:
                agent._pending_steer = steer_text
    else:
        existing = getattr(agent, '_pending_steer', None)
        agent._pending_steer = existing + '\n' + steer_text if existing else steer_text
